const WINDOW_SECONDS = 60;
const MAX_REQUESTS = 10;
const userId = $input.first().json.user_id || "anonymous";
const prompt = $input.first().json.prompt;
const sessionId = $input.first().json.session_id;
const now = Date.now();
const windowStart = now - (WINDOW_SECONDS * 1000);
const state = $workflow.staticData;
if (!state.rateLimits) state.rateLimits = {};
if (!state.rateLimits[userId]) state.rateLimits[userId] = { timestamps: [] };
const userRecord = state.rateLimits[userId];
userRecord.timestamps = userRecord.timestamps.filter(ts => ts > windowStart);
const requestCount = userRecord.timestamps.length;
const allowed = requestCount < MAX_REQUESTS;
const remaining = Math.max(0, MAX_REQUESTS - requestCount);
const oldestTs = userRecord.timestamps.length > 0 ? userRecord.timestamps[0] : now;
const resetAt = new Date(oldestTs + (WINDOW_SECONDS * 1000)).toISOString();
const retryAfterSeconds = allowed ? 0 : Math.ceil((oldestTs + (WINDOW_SECONDS * 1000) - now) / 1000);
if (allowed) userRecord.timestamps.push(now);
return [{ json: {
  user_id: userId,
  prompt: prompt,
  session_id: sessionId,
  allowed: allowed,
  requests_made: requestCount + (allowed ? 1 : 0),
  requests_remaining: allowed ? remaining - 1 : remaining,
  limit: MAX_REQUESTS,
  window_seconds: WINDOW_SECONDS,
  reset_at: resetAt,
  retry_after_seconds: retryAfterSeconds
} }];
